// IBM Plex Sans, embedded (Latin + basic punctuation subset) for jsPDF text rendering.
// Font: IBM Plex Sans (SIL Open Font License 1.1) — https://github.com/IBM/plex
(function () {
  var IBM_PLEX_SANS_REGULAR = "";
  var IBM_PLEX_SANS_BOLD = "";

  window.registerIbmPlexFont = function (doc) {
    if (doc.__ibmPlexRegistered) return;
    doc.addFileToVFS('IBMPlexSans-Regular.ttf', IBM_PLEX_SANS_REGULAR);
    doc.addFont('IBMPlexSans-Regular.ttf', 'IBMPlexSans', 'normal');
    doc.addFileToVFS('IBMPlexSans-Bold.ttf', IBM_PLEX_SANS_BOLD);
    doc.addFont('IBMPlexSans-Bold.ttf', 'IBMPlexSans', 'bold');
    doc.__ibmPlexRegistered = true;
  };
})();